import{_ as a,o as l,c as e,a5 as i}from"./chunks/framework.bIR-4glx.js";const c=JSON.parse('{"title":"持续行动计划模板","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/consistency-plan.zh.md","filePath":"public/downloads/worksheets/consistency-plan.zh.md","lastUpdated":1795488252000}'),r={name:"public/downloads/worksheets/consistency-plan.zh.md"};function d(h,t,n,o,s,u){return l(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="持续行动计划模板" tabindex="-1">持续行动计划模板 <a class="header-anchor" href="#持续行动计划模板" aria-label="Permalink to &quot;持续行动计划模板&quot;">​</a></h1><p>用这份模板安排一次有结束日期的行动实验。它是 <a href="https://byoungd.github.io/up/templates/rhythm-ledger" target="_blank" rel="noreferrer">节律账本</a> 的补充：账本维护每周容量与阻力，这张实验卡细化其中一个卡点的改动、验收与停止条件。已有账本不必重抄，在相应字段引用记录即可；完成后把结论记回账本。</p><p>它是一种实践工具，不是心理测量，也不保证固定天数形成习惯。先填写自己确实知道的部分，未知项留作待核验；无需为了填满表格增加任务。</p><p>先读 <a href="https://byoungd.github.io/up/threads/practice/discipline-and-consistency" target="_blank" rel="noreferrer">自律与坚持实操</a>，选择需要排查的问题。日常安排沿用 <a href="https://byoungd.github.io/up/threads/part-4/daily-system" target="_blank" rel="noreferrer">生活系统篇</a> 与 <a href="https://byoungd.github.io/up/threads/part-4/rhythm-and-compounding" target="_blank" rel="noreferrer">节律篇</a>，不额外维护一套日程。状态与作品入口可放在 <a href="https://byoungd.github.io/up/templates/learning-state" target="_blank" rel="noreferrer">学习状态</a>，每周结论写入 <a href="https://byoungd.github.io/up/templates/weekly-review" target="_blank" rel="noreferrer">每周复盘</a>。个人记录保存在自己的笔记里，证据使用不含敏感信息的文件位置。</p><h2 id="可复制模板" tabindex="-1">可复制模板 <a class="header-anchor" href="#可复制模板" aria-label="Permalink to &quot;可复制模板&quot;">​</a></h2><h3 id="持续行动计划-—-一个目标" tabindex="-1">持续行动计划 — [一个目标] <a class="header-anchor" href="#持续行动计划-—-一个目标" aria-label="Permalink to &quot;持续行动计划 — \\[一个目标]&quot;">​</a></h3><p>更新日期：YYYY-MM-DD<br> 本轮周期：YYYY-MM-DD 至 YYYY-MM-DD<br> 复查日期或条件：</p><h4 id="目标与证据" tabindex="-1">目标与证据 <a class="header-anchor" href="#目标与证据" aria-label="Permalink to &quot;目标与证据&quot;">​</a></h4><ul><li>为什么现在值得做：</li><li>本轮只完成的一项结果：</li><li>当前基线及样本位置：</li><li>完成标准（能观察或检查）：</li><li>明确不在本轮范围内的内容：</li></ul><h4 id="现实预算" tabindex="-1">现实预算 <a class="header-anchor" href="#现实预算" aria-label="Permalink to &quot;现实预算&quot;">​</a></h4><ul><li>已有工作、照护与生活责任：</li><li>本轮可用窗口及总时长：</li><li>准备、执行、反馈分别需要多少时间：</li><li>机动窗口（没有也可以）：</li><li>不挪用的时间或资源：</li><li>需要协商或仍不确定的条件：</li></ul><h4 id="行动入口" tabindex="-1">行动入口 <a class="header-anchor" href="#行动入口" aria-label="Permalink to &quot;行动入口&quot;">​</a></h4><ul><li>当 [可识别事件] 发生后：</li><li>在 [可用地点] 打开 [材料/文件]：</li><li>先做 [一个具体动作]：</li><li>最大阻碍及本轮只改的一件事：</li><li>必须保留的联系或提醒：</li><li>结束前保存的下一步：</li></ul><h4 id="三个版本" tabindex="-1">三个版本 <a class="header-anchor" href="#三个版本" aria-label="Permalink to &quot;三个版本&quot;">​</a></h4><table tabindex="0"><thead><tr><th>版本</th><th>使用条件</th><th>具体动作与结束条件</th><th>保存什么</th></tr></thead><tbody><tr><td>最小版</td><td></td><td></td><td></td></tr><tr><td>标准版</td><td></td><td></td><td></td></tr><tr><td>扩展版（可不设）</td><td></td><td></td><td></td></tr></tbody></table><ul><li>最小版不能代替的训练或验证：</li><li>单次投入上限：</li><li>缩量条件：</li><li>暂停条件：</li></ul><h4 id="中断恢复" tabindex="-1">中断恢复 <a class="header-anchor" href="#中断恢复" aria-label="Permalink to &quot;中断恢复&quot;">​</a></h4><ul><li>状态文件与最近作品位置：</li><li>第一次恢复时如何复测：</li><li>恢复的第一个有限任务：</li><li>下次重新评估的日期或条件：</li><li>截止日期受影响时如何调整范围或协商：</li></ul><h4 id="本轮记录" tabindex="-1">本轮记录 <a class="header-anchor" href="#本轮记录" aria-label="Permalink to &quot;本轮记录&quot;">​</a></h4><table tabindex="0"><thead><tr><th>日期</th><th>计划动作</th><th>实际产物与位置</th><th>阻碍/代价</th><th>下一步</th></tr></thead></table><h4 id="周期复查" tabindex="-1">周期复查 <a class="header-anchor" href="#周期复查" aria-label="Permalink to &quot;周期复查&quot;">​</a></h4><ul><li>与基线相比发生了什么（附证据）：</li><li>哪些仍无法独立解释或完成：</li><li>安排是否超过预算或挤占已有责任：</li><li>继续的条件：</li><li>改方法的条件：</li><li>暂停或停止的条件：</li><li>本轮决定及依据：</li><li>下轮只改一件事：</li></ul><h2 id="填写实例-四周改进英文项目介绍" tabindex="-1">填写实例：四周改进英文项目介绍 <a class="header-anchor" href="#填写实例-四周改进英文项目介绍" aria-label="Permalink to &quot;填写实例：四周改进英文项目介绍&quot;">​</a></h2><p><strong>以下为虚构示例，时间和任务量只用于演示填写。</strong> 学习者需要在团队交流中，用英语说明自己正在开发的 AI 笔记整理工具。计划同时考虑工作与家庭安排。</p><h3 id="持续行动计划-—-英文项目介绍" tabindex="-1">持续行动计划 — 英文项目介绍 <a class="header-anchor" href="#持续行动计划-—-英文项目介绍" aria-label="Permalink to &quot;持续行动计划 — 英文项目介绍&quot;">​</a></h3><p>更新日期：2026-09-19<br> 本轮周期：2026-09-21 至 2026-10-18<br> 复查日期或条件：每周日；工作安排改变时提前复查</p><h4 id="目标与证据-1" tabindex="-1">目标与证据 <a class="header-anchor" href="#目标与证据-1" aria-label="Permalink to &quot;目标与证据&quot;">​</a></h4><ul><li>为什么现在值得做：下一轮团队交流要说明项目用途与局限。</li><li>本轮只完成的一项结果：独立完成 90 秒介绍并回答两个追问。</li><li>当前基线及样本位置：初次录音约 50 秒；examples/baseline.m4a。</li><li>完成标准：听众能复述用途、用户与一项局限；两个追问都能用自己的话回答，未知项明确说不知道。</li><li>明确不在本轮范围内的内容：口音模仿、完整产品路演、新功能开发。</li></ul><h4 id="现实预算-1" tabindex="-1">现实预算 <a class="header-anchor" href="#现实预算-1" aria-label="Permalink to &quot;现实预算&quot;">​</a></h4><ul><li>已有工作、照护与生活责任：工作日晚间有家庭事务，时间不稳定。</li><li>本轮可用窗口及总时长：每周两次午间各 20 分钟，周末一次 20 分钟；四周共 240 分钟。</li><li>准备、执行、反馈分别需要多少时间：每周共 10 / 35 / 15 分钟。</li><li>机动窗口：每周最多一个 10 分钟窗口，可能不可用，不计入基本预算。</li><li>不挪用的时间或资源：不占用已经约定的家庭时间，不用晚睡补缺席。</li><li>需要协商或仍不确定的条件：周末录音窗口需提前协商；反馈伙伴是否有空。</li></ul><h4 id="行动入口-1" tabindex="-1">行动入口 <a class="header-anchor" href="#行动入口-1" aria-label="Permalink to &quot;行动入口&quot;">​</a></h4><ul><li>当周二、周四午饭结束且午休仍可用时：</li><li>在工位打开 notes/project-intro.md：</li><li>先做：写下今天要解释的一个要点。</li><li>最大阻碍及本轮只改的一件事：资料分散；只使用这一份提纲。</li><li>必须保留的联系或提醒：工作值班和家庭紧急联系。</li><li>结束前保存的下一步：未说清的问题及下次要用的例子。</li></ul><h4 id="三个版本-1" tabindex="-1">三个版本 <a class="header-anchor" href="#三个版本-1" aria-label="Permalink to &quot;三个版本&quot;">​</a></h4><table tabindex="0"><thead><tr><th>版本</th><th>使用条件</th><th>具体动作与结束条件</th><th>保存什么</th></tr></thead><tbody><tr><td>最小版</td><td>只有 5 分钟</td><td>写三句解释并标出一个不确定表达</td><td>三句话和一个问题</td></tr><tr><td>标准版</td><td>有 20 分钟</td><td>午间改提纲；周末录音、回听并改一处</td><td>提纲或录音及修改记录</td></tr><tr><td>扩展版</td><td>当周任务完成且机动窗口可用</td><td>用不同说法回答一个追问，10 分钟结束</td><td>一条问答记录</td></tr></tbody></table><ul><li>最小版不能代替的训练或验证：实际开口、即时追问与真实听众反馈。</li><li>单次投入上限：20 分钟；扩展版另限 10 分钟。</li><li>缩量条件：临时工作占用一个窗口，只保留一个要点。</li><li>暂停条件：本周没有可用窗口，保存状态到下周复查。</li></ul><h4 id="中断恢复-1" tabindex="-1">中断恢复 <a class="header-anchor" href="#中断恢复-1" aria-label="Permalink to &quot;中断恢复&quot;">​</a></h4><ul><li>状态文件与最近作品位置：notes/learning-state.md；recordings/。</li><li>第一次恢复时如何复测：不看提纲讲 30 秒，比较基线并记录缺口。</li><li>恢复的第一个有限任务：讲清楚一个用途，保存录音后结束。</li><li>下次重新评估的日期或条件：下一个周日，或工作排班确认后。</li><li>截止日期受影响时如何调整范围或协商：先用短版介绍，提前与团队确认；不承诺已完成全部训练。</li></ul><h4 id="本轮记录-1" tabindex="-1">本轮记录 <a class="header-anchor" href="#本轮记录-1" aria-label="Permalink to &quot;本轮记录&quot;">​</a></h4><table tabindex="0"><thead><tr><th>日期</th><th>计划动作</th><th>实际产物与位置</th><th>阻碍/代价</th><th>下一步</th></tr></thead><tbody><tr><td>2026-09-22</td><td>写用途与用户要点</td><td>notes/project-intro.md 中三句话</td><td>临时消息后只剩 5 分钟，用最小版</td><td>下次检查一处表达</td></tr><tr><td>2026-09-26</td><td>周末录音</td><td>recordings/week-1.m4a，60 秒</td><td>未能讲清工具局限，未超预算</td><td>先写一条具体局限</td></tr></tbody></table><h4 id="周期复查-1" tabindex="-1">周期复查 <a class="header-anchor" href="#周期复查-1" aria-label="Permalink to &quot;周期复查&quot;">​</a></h4><ul><li>与基线相比发生了什么（附证据）：第一周录音包含用途与用户，尚未验证听众能否理解。</li><li>哪些仍无法独立解释或完成：工具局限；两个即兴追问尚未练习。</li><li>安排是否超过预算或挤占已有责任：第一周未超预算，但周二窗口只有 5 分钟。</li><li>继续的条件：目标仍需要，窗口可用，录音或反馈显示具体改善。</li><li>改方法的条件：投入后仍只是在背提纲，增加不看稿的解释与反馈。</li><li>暂停或停止的条件：窗口消失则暂停；团队交流需求取消则重新评估用途。</li><li>本轮决定及依据：继续下一周，先补局限；现有记录不足以判断四周效果。</li><li>下轮只改一件事：请反馈伙伴用一句话复述听到的局限；如果对方无空，记录反馈缺失。</li></ul><p>实例中的第一周记录展示了不完整的结果：任务尚未达标，但下一步已经明确。最终复查仍需补齐四周证据，不能把计划本身当作效果证明。</p><h2 id="让-ai-帮助整理-而不替你制造进展" tabindex="-1">让 AI 帮助整理，而不替你制造进展 <a class="header-anchor" href="#让-ai-帮助整理-而不替你制造进展" aria-label="Permalink to &quot;让 AI 帮助整理，而不替你制造进展&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下面是我的持续行动计划和本轮真实记录。请检查时间预算是否相互矛盾、完成标准能否观察、最小版是否被误当作完整训练。指出证据缺口，不补造未完成的任务或反馈。根据已有责任，只建议下一轮的一项调整。若缺少关键事实，请明确标出需要我核实的条件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[粘贴计划与记录]</span></span></code></pre></div><p>接受建议前，核对日程、作品和相关人的实际安排。根据现实改变计划，是这份模板的一部分。</p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/consistency-plan" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-19。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>`,47)])])}const p=a(r,[["render",d]]);export{c as __pageData,p as default};
